style:
body{margin:0;background:#FFFFFF}
*{box-sizing:border-box}
img{max-width:100%}
summary::-webkit-details-marker{display:none}
.preview-banner{background:#111827;color:#E5E7EB;font:500 13px/1.5 'Noto Sans',sans-serif;padding:10px 16px;text-align:center;overflow-wrap:anywhere}
iframe.gmap{width:100%;height:440px;border:0;border-radius:14px;display:block;box-shadow:0 4px 16px 1px rgba(0,0,0,.10)}
@media (max-width: 860px){
  .r-cols{grid-template-columns:minmax(0,1fr)!important}
  .r-flow{flex-direction:column!important}
  .r-arrow{transform:rotate(90deg)!important}
  .r-arrowpad{padding:6px 0!important}
  .r-van{left:50%!important;right:auto!important;transform:translateX(-50%)!important;bottom:-110px!important;width:300px!important}
  .r-cardpad{padding:36px 24px 170px!important}
  .r-padb{padding-bottom:130px!important}
  nav[aria-label="Primary"]{display:none!important}
  header a[href^="tel:"]{display:none!important}
  header > div{gap:12px!important}
  aside[style*="sticky"]{position:static!important}
  iframe.gmap{height:300px}
}

/* Live WordPress footer */
#live-site-footer{--primary-color:#09263A;--secondary-color:#DD382B;font-family:var(--font-noto-sans),"Noto Sans",sans-serif;font-size:16px;line-height:normal;color:#0C1E35;background:#fff}
#live-site-footer *,#live-site-footer *::before,#live-site-footer *::after{box-sizing:border-box;margin:0;padding:0}
#live-site-footer .container{max-width:1170px;width:100%;padding:0 15px;margin:0 auto}
#live-site-footer img{height:auto;object-fit:cover;display:block;max-width:100%;border-radius:0}
#live-site-footer h4{font-family:var(--font-ubuntu),Ubuntu,sans-serif;font-size:clamp(20px,3.5vw,28px);line-height:clamp(28px,4.5vw,36px);font-weight:600;margin-bottom:12px;letter-spacing:normal;color:#0C1E35}
#live-site-footer p{font-size:clamp(16px,2.5vw,18px);line-height:clamp(24px,3vw,26px)}
#live-site-footer a{font-size:18px;line-height:26px;text-decoration:none;letter-spacing:normal}
#live-site-footer li{font-size:18px;line-height:26px}
#live-site-footer strong{font-family:inherit;font-weight:700}
#live-site-footer svg{flex-shrink:0}
#live-site-footer .footer-bottom a{color:#fff}
#live-site-footer .site-footer{
        background-color: #fff;
        color: #0c1e35;
        font-size: 16px;
        padding: 80px 0px 80px;
    }#live-site-footer .footer-columns{
        display: flex;
        flex-wrap: wrap;
        justify-content: space-between;
        gap: 24px;
    }#live-site-footer .footer-col{
        flex: 1 1 auto;
    }#live-site-footer .footer-col p{
        font-size: 14px;
        line-height: 24px;
        margin-bottom: 10px;
    }#live-site-footer .footer-col.about p{
        max-width: 345px;
    }#live-site-footer .footer-logo{
        width: 200px;
        margin-bottom: 20px;
    }#live-site-footer .site-footer.footer-col h4{
        margin-bottom: 20px;
        font-weight: 700;
    }#live-site-footer .site-footer .footer-col ul{
        list-style: none;
        padding: 0;
        margin: 0;
    }#live-site-footer .site-footer .footer-col.two-col ul{
        max-height: 180px;
        display: flex;
        flex-direction: column;
        flex-wrap: wrap;
    }#live-site-footer .site-footer .footer-col ul li{
        margin-bottom: 10px;
        padding-left: 0;
    }#live-site-footer .site-footer .footer-col.service-link a{
        color: #6A6A6A;
    }#live-site-footer .site-footer .footer-col a{
        color: var(--primary-color);
        text-decoration: none;
        transition: color 0.3s ease;
        font-size: 16px;
    }#live-site-footer .site-footer .footer-col a:hover{
        color: var(--secondary-color);
    }#live-site-footer .site-footer a.phone-btn{
        background-color: var(--secondary-color);
        color: #ffffff;
        padding: 10px 16px;
        margin-bottom: 15px;
        border-radius: 6px;
        font-weight: bold;
        text-decoration: none;
        display: inline-flex;
        align-items: center;
        justify-content: center;
        gap: 5px;
        vertical-align: middle;
        text-align: center;
    }#live-site-footer .site-footer a.phone-btn:hover,#live-site-footer .site-footer a.phone-btn:focus{
        opacity: 0.8;
        color: #ffffff;
    }#live-site-footer .site-footer .social-col{
        margin-top: 20px;
    }#live-site-footer .site-footer .social-icons{
        display: flex;
        gap: 24px;
        margin-top: 10px;
    }#live-site-footer .site-footer .social-icons .icon{
        width: 40px;
        height: 40px;
    }#live-site-footer .site-footer .social-icons svg path,#live-site-footer .site-footer .social-icons svg circle{
        fill: #fff;
    }#live-site-footer .social-icons .svg-icon{
        border-radius: 50%;
        width: 40px;
        height: 40px;
        display: inline-flex;
        align-items: center;
        justify-content: center;
        background: #DD382B;
        padding: 5px;
    }#live-site-footer .footer-bottom{
        background-color: var(--primary-color);
        color: #fff;
        text-align: center;
        padding: 12px 0;
        font-size: 14px;
    }#live-site-footer .footer-bottom p{
        margin-bottom: 0;
        font-size: clamp(14px, 2vw, 16px);
        padding: 0 15px;
    }#live-site-footer .site-footer .footer-col.contact{
        display: flex;
        flex-direction: column;
        align-items: start;
    }#live-site-footer .site-footer .footer-col.contact .links{
        display: inline-flex;
        gap: 4px;
        align-items: center;
    }#live-site-footer .site-footer .footer-col.contact .links a{
        font-weight: 600;
    }@media (max-width: 1074px){#live-site-footer .site-footer .footer-col.two-col ul{
            max-height: none;
        }}@media (max-width: 914px){#live-site-footer .site-footer .footer-col.contact{
            max-width: 350px;
        }}@media (max-width: 768px){#live-site-footer .site-footer .footer-columns{
            justify-content: center;
        }#live-site-footer .site-footer .footer-col.two-col ul{
            max-height: 100%;
        }#live-site-footer .footer-logo{
            width: 150px;
        }#live-site-footer .site-footer .social-icons{
            justify-content: center;
            gap: 20px;
        }}@media (max-width: 547px){#live-site-footer .site-footer{
            padding: 50px 0;
        }#live-site-footer .site-footer .footer-columns{
            flex-direction: column;
        }}
#live-site-footer .links a{overflow-wrap:anywhere}#live-site-footer :focus-visible{outline:3px solid #DD382B;outline-offset:3px}
